SELECT percentile_cont(0.9) within GROUP (ORDER BY (s.anchor_age - 80)) AS ninety_percentile, COUNT(*) filter (WHERE (s.anchor_age - 80) > 0) AS patients_with_instability_score, SUM(CASE WHEN d.deathtime IS NOT NULL THEN 1 ELSE 0 END) filter (WHERE (s.anchor_age - 80) > 0) AS patients_with_death, SUM(CASE WHEN i.los > 10 THEN 1 ELSE 0 END) filter (WHERE (s.anchor_age - 80) > 0) AS patients_with_long_icu_stay FROM icu_patients s JOIN chartevents c ON s.hadm_id = c.hadm_id JOIN datetimesevents dte ON c.charttime = dte.charttime JOIN icustays i ON s.hadm_id = i.hadm_id WHERE s.gender = 'F' AND s.anchor_age BETWEEN 75 AND 85 AND i.ventilation_mode = 'IMV' AND dte.value = 'Hypotension' AND dte.valueuom = 'mmHg' AND dte.seq_num = 1 AND c.itemid = 42675 AND c.icd_version = '2018' AND dte.charttime BETWEEN (i.intime - interval '48 hours') AND i.intime;